// Install @babel/core and babel-plugin-react-compiler@1.0.0 in a temporary
// directory, then pass its package.json path as the first argument.
import { createRequire } from 'node:module'
import { readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
const require = createRequire(resolve(process.argv[2]))
const { transformSync } = require('@babel/core')
const compiler = require('babel-plugin-react-compiler')
const version = require('babel-plugin-react-compiler/package.json').version
const output = transformSync(readFileSync(new URL('./input.txt', import.meta.url), 'utf8'), {
  filename: 'CompilerCounter.jsx', babelrc: false, configFile: false,
  parserOpts: { plugins: ['jsx'] }, plugins: [[compiler, { target: '19' }]],
}).code
if (!output.includes('react/compiler-runtime')) throw Error('Fixture was not compiled')
writeFileSync(new URL('./generated.jsx', import.meta.url),
  `// Generated by babel-plugin-react-compiler ${version}, target 19. Source: input.txt.\n${output}\n`)
